#include <bits/stdc++.h>
using namespace std;

using ll = long long; 
const int M = 998244353;
ll power(ll a, ll b) {
    if (a == 0) return 0;
    if (b == 0) return 1;
    if (b == 1) return a;
    
    ll ans = power(a, b/ 2);
    ans *= ans;
    ans %= M;
    if (b & 1) {
        ans *= a;
        ans %= M; 
    }
    return ans; 
}
void solve() {
    int n; cin >> n;
    vector<ll> a(n), p(n), s(n); 
    for (int i = 0; i < n; i++) {
        cin >> a[i]; 
    }
    for (int i = 1; i < n; i++) {
        p[i] = p[i - 1] + power(i, M - 2);
        p[i] %= M; 
    }
    for (int i = n - 2; i >= 0; i--) {
        int x = n - 1 - i; 
        s[i] = s[i + 1] + power(x, M - 2);
        s[i] %= M; 
    }
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        ll x = p[i] + s[i];
        x %= M; 
        x *= a[i]; 
        x %= M; 
        ans += x;
        ans %= M; 
    }
    cout << ans << "\n"; 
}
int main() {
	// your code goes here
	int t; cin >> t;
	while (t--) {
	    solve(); 
	}
}
